dr AS (SELECT DISTINCT cbo_2002 c FROM `basedosdados.br_bd_diretorios_brasil.cbo_2002`),
b AS (SELECT sigla_uf uf, cbo_2002 c, SUBSTR(cnae_2,1,2) d, COUNT(*) q FROM `basedosdados.br_me_rais.microdados_vinculos` WHERE ano=2025 AND vinculo_ativo_3112='1' AND valor_remuneracao_media>0 GROUP BY 1,2,3),
s AS (SELECT uf, CASE WHEN d IN ('01','02','03') THEN 'A' WHEN d BETWEEN '05' AND '09' THEN 'B' WHEN d BETWEEN '10' AND '33' THEN 'C' WHEN d='35' THEN 'D' WHEN d BETWEEN '36' AND '39' THEN 'E' WHEN d BETWEEN '41' AND '43' THEN 'F' WHEN d BETWEEN '45' AND '47' THEN 'G' WHEN d BETWEEN '49' AND '53' THEN 'H' WHEN d IN ('55','56') THEN 'I' WHEN d BETWEEN '58' AND '63' THEN 'J' WHEN d BETWEEN '64' AND '66' THEN 'K' WHEN d='68' THEN 'L' WHEN d BETWEEN '69' AND '75' THEN 'M' WHEN d BETWEEN '77' AND '82' THEN 'N' WHEN d='84' THEN 'O' WHEN d='85' THEN 'P' WHEN d BETWEEN '86' AND '88' THEN 'Q' WHEN d BETWEEN '90' AND '93' THEN 'R' WHEN d BETWEEN '94' AND '96' THEN 'S' WHEN d='97' THEN 'T' WHEN d='99' THEN 'U' ELSE 'X' END sec, q, (dr.c IS NOT NULL) v, n.e14 e14, n.e34 e34, (un.c IS NOT NULL) isu FROM b LEFT JOIN dr ON dr.c=b.c LEFT JOIN n ON n.c=b.c LEFT JOIN un ON un.c=b.c)
SELECT uf, STRING_AGG(CONCAT(sec,':',CAST(tot AS STRING),':',CAST(mp AS STRING),':',CAST(ROUND(s14) AS STRING),':',CAST(ROUND(s34) AS STRING)), '|' ORDER BY sec) r FROM (
SELECT uf, sec, SUM(IF(v, q, 0)) tot, SUM(IF(v AND NOT isu, q, 0)) mp, SUM(IF(e14 IS NOT NULL, q*e14, 0)) s14, SUM(IF(e14 IS NOT NULL, q*e34, 0)) s34 FROM s GROUP BY uf, sec) GROUP BY uf ORDER BY uf